def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == '[':
            stack.append(char)
        elif char == '':
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack.pop()
            if top != '(':
                return False
    return not stack

def mediana(nums):
    if not nums:
        return None
    n = len(nums)
    if n % 2 == 1:
        return nums[n // 2]
    else:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2

