def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    resultados = []
    i = 0
    while n > 0:
        n, rem = divmod(n, 1024)
        if i < len(unidades) and rem < 1:
            resultados.append(f"{unidades[i]} {rem:.0f}")
        else:
            resultados.append(unidades[i])
        i += 1
    return ' '.join(resultados)

