def contar_islas(grid):
    m, n = len(grid), len(grid[0])
    islas = []
    for i in range(m):
        for j in range(n):
            if i > 0 and grid[i-1][j] == 1:
                islas.append(i)
            if i < m-1 and grid[i+1][j] == 1:
                islas.append(i)
            if j > 0 and grid[i][j-1] == 1:
                islas.append(i)
            if j < n-1 and grid[i][j+1] == 1:
                islas.append(i)
    return len(islas)

